#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Sentry crash reporting for the Mibo mobile app (#35, ADR-0015).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Values live in EAS, not in the repo. This file is only the wizard's memory
# between runs, so a re-run can offer what you pasted last time; `.gitignore`
# already covers `.env.*`. The auth token is never written here.
ENV_FILE="apps/mobile/.env.local"

# ask_valid KEY "Prompt" REGEX "what it should look like" — `ask`, but it will
# not take an answer that cannot be the thing it asked for. The two values here
# are easy to hand each other: Sentry shows the DSN on the page you read the
# slug off, and a DSN ends in the project *id*, which looks like an answer to
# "project slug". Both mistakes are silent — an invalid DSN just means the SDK
# never starts — so they are caught at the prompt instead.
ask_valid() {
  local key="$1" prompt="$2" pattern="$3" shape="$4"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "that does not look like $shape — try again"
  done
}

banner "Sentry for the Mibo mobile app"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sentry — the project"
say "Sentry needs one project for the app. If you already have one, just read"
say "its slugs and DSN off the page instead of making another."
open_url "https://sentry.io/signup/"
step "Sign up, or sign in if you have an account."
step "Create an organization if you do not have one; note its slug — it is the"
step "  first part of your Sentry URL, <slug>.sentry.io."
step "Create a project: platform 'React Native', and name it something you will"
step "  recognise (the Android and iOS builds share it)."
pause "Project created?"
note "a slug is a short name, like 'mibo' — not a URL and not a number"
ask_valid SENTRY_ORG "Organization slug:" '^[a-z0-9][a-z0-9_-]*$' "an organization slug"
ask_valid SENTRY_PROJECT "Project slug:" '^[a-z0-9][a-z0-9._-]*$' "a project slug"
write_env SENTRY_ORG "$SENTRY_ORG"
write_env SENTRY_PROJECT "$SENTRY_PROJECT"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Sentry — the DSN"
say "The DSN is where the app sends events. It is a write-only ingest key —"
say "public by design — but it still does not go in the repo."
open_url "https://sentry.io/orgredirect/organizations/$SENTRY_ORG/settings/projects/$SENTRY_PROJECT/keys/"
step "Settings → Projects → $SENTRY_PROJECT → Client Keys (DSN)."
step "Copy the DSN. It looks like https://<hash>@o<number>.ingest.sentry.io/<id>."
ask_valid EXPO_PUBLIC_SENTRY_DSN "Paste the DSN:" \
  '^https://[0-9a-f]+@o[0-9]+\.ingest\.([a-z]+\.)?sentry\.io/[0-9]+$' "a DSN"
write_env EXPO_PUBLIC_SENTRY_DSN "$EXPO_PUBLIC_SENTRY_DSN"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Sentry — the auth token"
say "This one uploads source maps at build time, so a stack trace in the"
say "dashboard names your files and lines instead of minified bundle offsets."
say "It can read the project, so it is the one value that is a real secret."
open_url "https://sentry.io/orgredirect/organizations/$SENTRY_ORG/settings/auth-tokens/"
step "Settings → Auth Tokens → Create New Token (an organization token)."
step "Give it the scopes the upload needs: project:releases and org:read."
step "Copy it now — Sentry shows an org token once and never again."
ask_secret SENTRY_AUTH_TOKEN "Paste the auth token (hidden):"
note "not written to $ENV_FILE — it goes straight to EAS in the next stage"
if [[ -z "$SENTRY_AUTH_TOKEN" ]]; then
  warn "no token given — source maps will not upload"
  SKIPPED+=("SENTRY_AUTH_TOKEN in EAS (re-run this wizard, or: eas env:set preview --name SENTRY_AUTH_TOKEN --visibility secret)")
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "EAS — push the four values"
say "These go to the 'preview' environment, which is the profile that builds"
say "the internal APK. eas.json holds no Sentry values on purpose: the auth"
say "token must not be committed, so all four live here together."
if ! command -v eas >/dev/null 2>&1; then
  warn "the eas CLI is not on PATH — install it with: npm i -g eas-cli"
  SKIPPED+=("all four EAS variables (install eas-cli, then re-run this wizard)")
else
  eas whoami >/dev/null 2>&1 || { step "Signing you in to Expo."; eas login; }
  set_eas() {
    local name="$1" value="$2" visibility="$3"
    [[ -z "$value" ]] && return 0
    if (cd apps/mobile && eas env:set preview \
          --name "$name" --value "$value" \
          --visibility "$visibility" --scope project --non-interactive >/dev/null 2>&1); then
      printf '  %s✓ set%s EAS preview variable %s (%s)\n' "$GREEN" "$RESET" "$name" "$visibility"
    else
      warn "could not set $name"
      SKIPPED+=("EAS variable $name")
    fi
  }
  # EXPO_PUBLIC_* is inlined into the bundle at build time, so it cannot be
  # 'secret' — a secret variable is write-only and the build could not read it.
  set_eas EXPO_PUBLIC_SENTRY_DSN "$EXPO_PUBLIC_SENTRY_DSN" sensitive
  set_eas SENTRY_ORG "$SENTRY_ORG" plaintext
  set_eas SENTRY_PROJECT "$SENTRY_PROJECT" plaintext
  set_eas SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN" secret
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Build a preview APK"
say "Nothing initialises in development, so a dev build proves nothing here."
say "This needs a release build, and it takes ten to fifteen minutes."
if confirm "Start the EAS build now?"; then
  (cd apps/mobile && eas build --platform android --profile preview) || {
    warn "the build did not finish"
    SKIPPED+=("preview APK build: cd apps/mobile && eas build -p android --profile preview")
  }
else
  SKIPPED+=("preview APK build: cd apps/mobile && eas build -p android --profile preview")
fi
step "When it finishes, install the APK on a device or emulator."
pause "Installed?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Trigger an error and read the raw payload"
say "This is the acceptance criterion no test can cover: what actually leaves"
say "a real device. Two things to check, in this order."
step "In the app, force the handled path: tap 'Continue with Google' on the"
step "  parent sign-in screen and cancel the browser. That is the catch in"
step "  parent-sign-in.tsx, tagged where=parent-sign-in.google."
open_url "https://sentry.io/orgredirect/organizations/$SENTRY_ORG/issues/?project=$SENTRY_PROJECT"
step "The issue should appear with a readable stack trace naming .tsx files —"
step "  if the frames are bundle offsets, the source maps did not upload."
pause "Event arrived?"
say ""
say "Now the anonymity check (ADR-0009). Open the event, then:"
step "Scroll to the bottom of the event and open 'JSON' (the raw payload)."
step "Search it for a child's first name, the pet name, a chore title and a"
step "  Join Code. None of the four may appear anywhere — not in tags, not in"
step "  breadcrumbs, not in a URL, not in contexts."
step "Then do the same for an event from a kid device, and check it has no"
step "  'user' object at all and is tagged mode=kid."
if confirm "Payload clean — no child data anywhere?"; then
  say "That is acceptance criteria 2 and 4 of issue #35 met."
else
  warn "stop and report what you found before shipping this"
  SKIPPED+=("a leak in the raw payload — do not release until it is closed")
fi

finish
